import { Component, Element, Fragment, Host, Prop, h } from "@stencil/core";

const VARIANT_PROPS = {
	"text:body": {
		size: "small",
		strong: false,
	},
	"text:primary-title": {
		size: "large",
		strong: true,
	},
	"text:section-title": {
		size: "medium",
		strong: true,
	},
	"layout:basic-card": {
		size: "custom",
		strong: false,
	},
	"layout:statistics-or-status-cards": {
		size: "custom",
		strong: false,
	},
	"layout:table": {
		size: "custom",
		strong: false,
	},
	"layout:key-value-pairs:horizontal": {
		size: "custom",
		strong: false,
	},
	"layout:key-value-pairs:vertical": {
		size: "custom",
		strong: false,
	},
	"layout:list": {
		size: "custom",
		strong: false,
	},
	"layout:chart": {
		size: "custom",
		strong: false,
	},
} as const;

const DEFAULTS = {
	size: "small",
	strong: false,
} as const;

/**
 * A low-fidelity placeholder that previews the shape of content while it loads.
 *
 * @since 2.18.54
 * @status beta
 *
 * @example
 * <hbr-skeleton variant="text:body" />
 *
 * @example
 * <hbr-skeleton size="custom" style="width: 250px; height: 160px" />
 */
@Component({
	tag: "hbr-skeleton",
	styleUrl: "skeleton.scss",
	scoped: false,
})
export class Skeleton {
	@Element() el!: HTMLHbrSkeletonElement;

	/** Semantic preset for common text and layout loading patterns. */
	@Prop({ reflect: true }) variant?:
		| "text:section-title"
		| "text:primary-title"
		| "text:body"
		| "layout:basic-card"
		| "layout:statistics-or-status-cards"
		| "layout:table"
		| "layout:key-value-pairs:horizontal"
		| "layout:key-value-pairs:vertical"
		| "layout:list"
		| "layout:chart";

	/** Height preset. Use custom with an explicit CSS height. */
	@Prop() size?: "small" | "medium" | "large" | "custom";

	/** Uses the stronger placeholder background color. */
	@Prop() strong?: boolean;

	/** Number of body rows rendered by the table template. */
	@Prop() rows = 10;

	componentWillRender() {
		const variantProps = this.variant ? VARIANT_PROPS[this.variant] : null;

		// Priority: explicit prop > variant default > component default
		const finalSize = this.size || variantProps?.size || DEFAULTS.size;
		const finalStrong = this.strong ?? variantProps?.strong ?? DEFAULTS.strong;

		this.el.setAttribute("size", finalSize);
		if (finalStrong) {
			this.el.setAttribute("strong", "");
		} else {
			this.el.removeAttribute("strong");
		}
	}

	private renderBasicCard() {
		return (
			<hbr-card
				container={true}
				style={{
					width: "100%",
					"--container-gap": "var(--hbr-spacing-lg)",
				}}
			>
				<hbr-skeleton
					slot="header"
					size="medium"
					style={{ width: "60%" }}
					strong
				/>
				<hbr-layout direction="column" gap="sm">
					<hbr-skeleton />
					<hbr-skeleton />
					<hbr-skeleton style={{ width: "70%" }} />
				</hbr-layout>
			</hbr-card>
		);
	}

	private renderStatisticsOrStatusCards() {
		return (
			<hbr-card container={true} style={{ width: "100%" }}>
				<hbr-layout align="center">
					<hbr-skeleton style={{ width: "60%" }} />
					<hbr-skeleton
						style={{
							width: "36px",
							height: "36px",
							borderRadius: "var(--hbr-border-radius-md)",
							marginLeft: "auto",
						}}
					/>
				</hbr-layout>
			</hbr-card>
		);
	}

	private renderTable() {
		const rowCount =
			Number.isFinite(this.rows) && this.rows > 0 ? Math.floor(this.rows) : 10;

		return (
			<hbr-layout direction="column" gap="2xs">
				<hbr-layout gap="sm">
					{Array.from({ length: 4 }, (_, column) => (
						<hbr-skeleton
							// biome-ignore lint/suspicious/noArrayIndexKey: Static skeleton columns never reorder.
							key={`header-${column}`}
							size="small"
							strong
						/>
					))}
				</hbr-layout>
				<hbr-divider />
				{Array.from({ length: rowCount }, (_, row) => (
					// biome-ignore lint/suspicious/noArrayIndexKey: Static skeleton rows never reorder.
					<div key={`row-${row}`}>
						<div
							style={{
								display: "grid",
								gridTemplateColumns: "repeat(4, minmax(0, 1fr))",
								gap: "var(--hbr-spacing-lg)",
								padding: "var(--hbr-spacing-2xs) 0",
							}}
						>
							{Array.from({ length: 4 }, (_, column) => (
								// biome-ignore lint/suspicious/noArrayIndexKey: Static skeleton cells never reorder.
								<hbr-skeleton key={`cell-${row}-${column}`} size="small" />
							))}
						</div>
						{row < rowCount - 1 && <hbr-divider />}
					</div>
				))}
			</hbr-layout>
		);
	}
	private renderHorizontalKeyValuePairs() {
		return (
			<hbr-layout direction="column" gap="none">
				{Array.from({ length: 3 }, (_, row) => (
					// biome-ignore lint/suspicious/noArrayIndexKey: Static skeleton pairs never reorder.
					<div key={`pair-${row}`}>
						<hbr-layout
							display="grid"
							align="start"
							gap="lg"
							class="skeleton-key-value-row"
						>
							<hbr-skeleton size="small" strong />
							<hbr-layout direction="column" gap="sm">
								<hbr-skeleton size="small" />
								{row > 0 && (
									<Fragment>
										<hbr-skeleton size="small" />
										<hbr-skeleton size="small" style={{ width: "75%" }} />
									</Fragment>
								)}
							</hbr-layout>
						</hbr-layout>
						{row < 2 && <hbr-divider />}
					</div>
				))}
			</hbr-layout>
		);
	}
	private renderVerticalKeyValuePairs() {
		return (
			<hbr-layout direction="column" gap="lg">
				{Array.from({ length: 4 }, (_, row) => (
					// biome-ignore lint/suspicious/noArrayIndexKey: Static skeleton pairs never reorder.
					<hbr-layout key={`pair-${row}`} direction="column" gap="sm">
						<hbr-skeleton size="small" style={{ width: "40%" }} />
						<hbr-skeleton size="small" strong />
					</hbr-layout>
				))}
			</hbr-layout>
		);
	}

	private renderList() {
		return (
			<hbr-layout direction="column" gap="lg">
				{Array.from({ length: 3 }, (_, item) => (
					// biome-ignore lint/suspicious/noArrayIndexKey: Static skeleton items never reorder.
					<hbr-layout key={`item-${item}`} align="start">
						<hbr-skeleton
							size="custom"
							style={{ width: "60px", height: "60px" }}
						/>
						<hbr-layout direction="column" gap="sm" style={{ width: "100%" }}>
							<hbr-skeleton size="small" />
							<hbr-skeleton size="small" style={{ width: "70%" }} />
						</hbr-layout>
					</hbr-layout>
				))}
			</hbr-layout>
		);
	}

	private renderChart() {
		return (
			<hbr-layout direction="column" gap="lg">
				<hbr-skeleton size="medium" strong style={{ width: "40%" }} />
				<div class="skeleton-chart">
					<hbr-skeleton size="custom" style={{ height: "220px" }} />
					<hbr-layout direction="column" gap="sm">
						{Array.from({ length: 6 }, (_, item) => (
							// biome-ignore lint/suspicious/noArrayIndexKey: Static skeleton legend items never reorder.
							<hbr-skeleton key={`legend-${item}`} size="small" />
						))}
					</hbr-layout>
				</div>
			</hbr-layout>
		);
	}

	private renderTemplate() {
		switch (this.variant) {
			case "layout:basic-card":
				return this.renderBasicCard();
			case "layout:statistics-or-status-cards":
				return this.renderStatisticsOrStatusCards();
			case "layout:table":
				return this.renderTable();
			case "layout:key-value-pairs:horizontal":
				return this.renderHorizontalKeyValuePairs();
			case "layout:key-value-pairs:vertical":
				return this.renderVerticalKeyValuePairs();
			case "layout:list":
				return this.renderList();
			case "layout:chart":
				return this.renderChart();
			default:
				return null;
		}
	}

	render() {
		return <Host aria-hidden="true">{this.renderTemplate()}</Host>;
	}
}
